import React from 'react';

const QuanLyCanHo = () => {
    const apartments = [
        { id: '101', loai: '2 PN', status: 'Đang ở', chu: 'Phan Vinh' },
        { id: '102', loai: '1 PN', status: 'Trống', chu: '---' },
        { id: '103', loai: 'Studio', status: 'Đang ở', chu: 'Trần B' },
    ];

    return (
        <div>
            <h2>🏠 Danh sách căn hộ</h2>
            <div style={gridStyle}>
                {apartments.map(ap => (
                    <div key={ap.id} style={{...cardStyle, borderTop: `6px solid ${ap.status === 'Trống' ? '#9e9e9e' : '#a52a2a'}`}}>
                        <h3>Phòng {ap.id}</h3>
                        <p>Loại: {ap.loai}</p>
                        <p>Chủ hộ: <b>{ap.chu}</b></p>
                        <div style={{...statusTag, backgroundColor: ap.status === 'Trống' ? '#e0e0e0' : '#fbe9e7', color: ap.status === 'Trống' ? '#616161' : '#d84315'}}>
                            {ap.status}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

const gridStyle = { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '20px' };
const cardStyle = { backgroundColor: '#fff', padding: '20px', borderRadius: '12px', textAlign: 'center', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' };
const statusTag = { display: 'inline-block', padding: '5px 15px', borderRadius: '20px', fontSize: '12px', marginTop: '10px' };

export default QuanLyCanHo;
